async createContractVersion(contractId, draft, ctx) {
    const contract = await contracts.get(contractId);
    assertEditableState(contract.status);
    const rendered = await renderer.render(draft.templateVersionId, draft.data);
    const hash = sha256(rendered.bytes);
    return versions.create({
        contractId,
        versionNo: await versions.nextNumber(contractId),
        templateVersionId: draft.templateVersionId,
        contentHash: hash,
        fileId: await files.store(rendered.bytes),
        status: 'DRAFT',
        createdBy: ctx.userId,
    });
}

async assertRequirementsSatisfied(contractId, targetStage, ctx) {
    const requirements = await requirementService.resolve(contractId, targetStage);
    const missing = requirements.filter(r => !r.satisfied);
    if (missing.length) {
        throw new ContractRequirementsMissingError(missing.map(x => x.code));
    }
}

async approveVersion(versionId, ctx) {
    await assertPermission(ctx, 'contracts.version.approve');
    const v = await versions.get(versionId);
    await assertRequirementsSatisfied(v.contractId, 'LEGAL_APPROVAL', ctx);
    assertHashMatchesStoredFile(v);
    await versions.markApproved(v.id, ctx.userId);
    await outbox.append(...contractVersionApprovedEvent(v));
}

export interface SignatureAdapter {
    createEnvelope(req: SignatureEnvelopeRequest): Promise<{ externalId: string }>;
    cancelEnvelope(externalId: string): Promise<void>;
    getStatus(externalId: string): Promise<SignatureEnvelopeStatus>;
    verifyWebhook(headers: Record<string,string>, rawBody: Buffer): boolean;
}

async handleSignatureWebhook(provider, rawBody, headers) {
    adapter.verifyWebhook(headers, rawBody);
    const event = parseProviderEvent(rawBody);
    const inserted = await integrationInbox.tryInsert(provider, event.id, hash(rawBody));
    if (!inserted) return;
    await signatureService.applyProviderEvent(event);
}

interface InspectionItem {
    roomCode: string;
    itemCode: string;
    conditionCode: 'NEW'|'GOOD'|'REGULAR'|'DAMAGED';
    description?: string;
    mediaFileIds: string[];
}
async function signInspection(inspectionId, signer, ctx) {
    const inspection = await inspections.get(inspectionId);
    assertComplete(inspection);
    const snapshotHash = sha256(canonicalJson(inspection.snapshot));
    await inspections.freezeAndSign(inspectionId, signer, snapshotHash);
}

async deliverKeys(contractId, input, ctx) {
    await assertPermission(ctx, 'lease.keys.deliver');
    await assertRequirementsSatisfied(contractId, 'KEY_DELIVERY', ctx);
    const contract = await contracts.get(contractId);
    assertIn(['SIGNED','ACTIVE'], contract.status);
    return db.transaction(async tx => {
        const delivery = await keyDeliveries.create(tx, input);
        await outbox.append(tx, keysDeliveredEvent(contract, delivery, ctx));
        return delivery;
    });
}

async createDeadline(input, ctx) {
    if (!input.sourceFileId && !input.sourceEventId) {
        throw new ValidationError('DEADLINE_SOURCE_REQUIRED');
    }
    const d = await deadlines.create(input);
    await tasks.create({
        responsibleUserId: d.responsibleUserId,
        dueAt: d.dueAt,
        severity: d.severity,
        sourceType: 'LEGAL_DEADLINE',
        sourceId: d.id,
    });
    return d;
}

async createEvidencePackage(caseId, fileIds, ctx) {
    const files = await fileRepo.getImmutableMetadata(fileIds);
    const manifest = files.map(f => ({
        fileId: f.id,
        sha256: f.sha256,
        originalName: f.originalName,
        createdAt: f.createdAt,
        source: f.source,
    }));
    const manifestHash = sha256(canonicalJson(manifest));
     return evidencePackages.store({ caseId, manifest, manifestHash, createdBy: ctx.userId });
 }
